function charCard(c){const role=window.ROLES.find(r=>r.id===c.role);return `<article class="character-card"><div class="char-art"><div class="char-art-grid"></div><span class="char-art-glyph">${esc((c.name||'N').slice(0,1).toUpperCase())}</span><span class="char-index">NC // ${esc(c.role.toUpperCase())}</span><span class="char-dot">✳</span></div><div class="char-body"><div class="char-kicker">${esc(val(role?.name)||c.role)} <span> / RANK ${Number(c.rank)||0}</span></div><h3>${esc(c.name||tr('untitled'))}</h3><div class="char-meta"><span>HP <strong>${Number(c.hp)||0}/${hpMax(c)}</strong></span><span>HUM <strong>${Number(c.humanity)||0}</strong></span><span>BODY <strong>${Number(c.stats.BODY)||0}</strong></span></div><button class="btn text-button" data-action="open" data-id="${esc(c.id)}">${tr('edit')} <span>↗</span></button></div></article>`}
function empty(){return `<div class="empty"><div class="empty-icon">✳</div><h3>${tr('empty')}</h3><p>${tr('emptyDesc')}</p>${createBtn()}</div>`}
function overview(){return `<div class="eyebrow"><span class="red-dot"></span> ${tr('subtitle')} <span> // 001</span></div><section class="hero"><div class="hero-copy"><div class="hero-label"><span>✳</span> ${tr('tag')}</div><h1>${tr('hero').replace('\n','<br>')}</h1><p>${tr('intro')}</p><div class="hero-actions">${createBtn()}<button class="btn ghost" data-action="navigate" data-view="rules">${tr('openRules')} <span>↗</span></button></div></div><div class="hero-art" aria-hidden="true"><div class="hero-orbit orbit-one"></div><div class="hero-orbit orbit-two"></div><div class="hero-sun"></div><div class="hero-cross">✳</div><div class="hero-coordinate">N 35° 41' 23"<br>W 120° 45' 10"</div><div class="hero-big">NC<span>///</span></div><div class="hero-side">NIGHT CITY &nbsp; • &nbsp; EST. 1994 &nbsp; • &nbsp; 2045</div></div><div class="hero-bottom"><span>WELCOME TO THE TIME OF THE RED</span><span>01 / 04</span></div></section><div class="section-head"><div><div class="overline">01 / PERSONNEL</div><h2>${tr('library')}</h2><p>${tr('libraryIntro')}</p></div><button class="btn subtle" data-action="navigate" data-view="characters">${tr('characters')} <span>↗</span></button></div><div class="character-grid">${state.characters.length?state.characters.slice(0,3).map(charCard).join(''):empty()}</div><div class="section-head"><div><div class="overline">02 / DATABASE</div><h2>${tr('quick')}</h2></div></div><div class="quick-grid"><button class="quick-card" data-action="navigate" data-view="rules"><span class="quick-icon">▥</span><span><b>${tr('quickRules')}</b><small>${tr('quickRulesSub')}</small></span><span class="quick-arrow">↗</span></button><button class="quick-card" data-action="navigate" data-view="dice"><span class="quick-icon">⬡</span><span><b>${tr('quickDice')}</b><small>${tr('quickDiceSub')}</small></span><span class="quick-arrow">↗</span></button></div><div class="source-strip"><div class="source-symbol">✳</div><div><strong>${tr('source')}</strong><p>${tr('sourceDesc')}</p></div></div>`}
function characters(){return `<div class="page-header"><div><div class="overline">01 / PERSONNEL DATABASE</div><h1>${tr('charactersTitle')}</h1><p>${tr('charsLead')}</p></div><div class="header-actions"><label class="btn ghost file-label">↓ ${tr('import')}<input type="file" accept="application/json,.json" id="import-file" hidden></label><label class="btn ghost file-label">↓ ${tr('importAll')}<input type="file" accept="application/json,.json" id="import-backup" hidden></label><label class="btn ghost file-label">↺ ${state.lang==='ru'?'Восстановить полностью':'Restore full backup'}<input type="file" accept="application/json,.json" id="restore-backup" hidden></label><button class="btn ghost" data-action="export-backup">↑ ${tr('exportAll')}</button><button class="btn ghost" data-action="new-blank">＋ ${state.lang==='ru'?'Пустой лист':'Blank sheet'}</button>${createBtn()}</div></div><div class="countbar"><span>${tr('library')}</span><b>${String(state.characters.length).padStart(2,'0')} / 2045</b></div><div class="character-grid">${state.characters.length?state.characters.map(charCard).join(''):empty()}</div>`}
function catalog(){const lang=state.lang,ru=lang==='ru',types={all:ru?'Все категории':'All categories',weapon:ru?'Оружие':'Weapons',armor:ru?'Броня':'Armor',gear:ru?'Снаряжение':'Gear',cyberware:ru?'Киберимпланты':'Cyberware',ammo:ru?'Боеприпасы':'Ammunition',attachment:ru?'Модификации':'Attachments',programs:ru?'Программы и кибердеки':'Programs and cyberdecks',fashion:ru?'Мода':'Fashion',services:ru?'Услуги':'Services',drugs:ru?'Вещества':'Drugs',housing:ru?'Жильё и образ жизни':'Housing and lifestyle',vehicles:ru?'Транспорт':'Vehicles',defenses:ru?'Защита помещений':'Home defenses'};return `<div class="page-header"><div><div class="overline">05 / NIGHT MARKET</div><h1>${ru?'КАТАЛОГ СНАРЯЖЕНИЯ':'EQUIPMENT CATALOG'}</h1><p>${ru?'Цены, параметры и страницы Corebook. Добавление в лист не списывает деньги и не устанавливает импланты.':'Prices, statistics and Corebook page references. Adding to a sheet does not spend money or install cyberware.'}</p></div><div class="header-marker">◇<small>NIGHT<br>MARKET</small></div></div><div class="catalog-toolbar"><label class="field">${ru?'Поиск':'Search'}<input id="catalog-search" placeholder="${ru?'Название или свойство...':'Name or property...'}" value="${esc(state.catalogQuery)}"></label><label class="field">${ru?'Категория':'Category'}<select id="catalog-category">${Object.entries(types).map(([k,v])=>`<option value="${k}" ${state.catalogCategory===k?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">${ru?'Добавить персонажу':'Add to character'}<select id="catalog-target"><option value="">${ru?'Выбери персонажа':'Choose a character'}</option>${state.characters.map(c=>`<option value="${esc(c.id)}" ${state.catalogTarget===c.id?'selected':''}>${esc(c.name||tr('untitled'))}</option>`).join('')}</select></label></div><div class="catalog-purchase"><label class="field">${ru?'Бюджет для покупки':'Purchase budget'}<select id="catalog-mode">${[['cash',ru?'Деньги':'Cash'],['gearBudget',ru?'Стартовое снаряжение':'Starting gear'],['fashionBudget',ru?'Стартовая одежда':'Starting fashion']].map(([v,n])=>`<option value="${v}" ${state.catalogMode===v?'selected':''}>${n}</option>`).join('')}</select></label><label class="field">${ru?'Количество / комнаты':'Quantity / rooms'}<input id="catalog-quantity" type="number" min="1" max="50" value="${Number(state.catalogQuantity)||1}"></label><label class="field">${ru?'Тип боеприпаса для покупки':'Ammunition type for purchase'}<select id="catalog-ammo-type"><option value="">${ru?'Выберите тип':'Choose a type'}</option>${[...new Map(window.CATALOG.filter(x=>x.category==='ammo').flatMap(x=>window.EquipmentTools.ammoTypeOptions(x,lang)).map(x=>[x.value,x.label])).entries()].map(([v,n])=>`<option value="${esc(v)}" ${state.catalogAmmoType===v?'selected':''}>${esc(n)}</option>`).join('')}</select></label><label class="field">${ru?'Тип Skill Chip':'Skill Chip type'}<select id="catalog-skill-chip"><option value="">${ru?'Выберите стоимость':'Choose cost'}</option>${window.EquipmentTools.skillChipOptions(window.CATALOG.find(x=>x.id==='cyberware-skill-chip'),lang).map(x=>`<option value="${esc(x.value)}" ${state.catalogSkillChipType===x.value?'selected':''}>${esc(x.label)} · ${x.price} eb</option>`).join('')}</select></label><p>${ru?'Для боеприпасов количество означает пачки по 10 или отдельные гранаты и ракеты; тип должен подходить выбранной позиции. ':'For ammunition, quantity means packs of 10 or individual grenades and rockets; the type must match the selected item. '}${ru?'«Добавить» — без оплаты. «Купить» — с подтверждением и списанием из выбранного бюджета. Для транспорта цена может быть за комнату.':'“Add” does not charge money. “Buy” requires confirmation and deducts from the selected budget. Vehicle pricing may be per room.'}</p></div><div class="catalog-grid" id="catalog-list">${window.renderCatalog(lang,state.catalogQuery,state.catalogCategory)}</div>`}
function filteredRules(){let q=state.query.toLocaleLowerCase().trim();return window.RULES.filter(r=>(state.ruleCategory==='all'||r.category.en===state.ruleCategory)&&(!q||[r.title.ru,r.title.en,r.text.ru,r.text.en,r.category.ru,r.category.en,String(r.page)].some(x=>String(x).toLocaleLowerCase().includes(q))))}
function rules(){let list=filteredRules(),categories=[...new Map(window.RULES.map(r=>[r.category.en,r.category])).values()];return `<div class="page-header"><div><div class="overline">02 / KNOWLEDGE DATABASE</div><h1>${tr('rulesTitle')}</h1><p>${tr('rulesLead')}</p></div><div class="header-marker">✳<small>COREBOOK<br>V1.22</small></div></div><div class="rules-toolbar"><label class="search"><span>⌕</span><input id="rules-search" value="${esc(state.query)}" placeholder="${tr('search')}" aria-label="${tr('search')}"><kbd>⌕</kbd></label><label class="rule-category"><span class="sr-only">${state.lang==='ru'?'Категория':'Category'}</span><select id="rules-category"><option value="all">${state.lang==='ru'?'Все категории':'All categories'}</option>${categories.map(c=>`<option value="${esc(c.en)}" ${state.ruleCategory===c.en?'selected':''}>${esc(val(c))}</option>`).join('')}</select></label><span class="result-count">${String(list.length).padStart(2,'0')} ${tr('showing')}</span></div><div id="rules-list" class="rules-grid">${rulesCards(list)}</div>`}
function refreshRules(){let list=filteredRules(),container=$('#rules-list');if(container)container.innerHTML=rulesCards(list);let count=$('.result-count');if(count)count.textContent=String(list.length).padStart(2,'0')+' '+tr('showing')}
function rulesCards(list){return list.length?list.map((r,i)=>`<article class="rule-card"><div class="rule-top"><span class="badge">${esc(val(r.category))}</span><span>${tr('page')} ${esc(r.page)}</span></div><h3>${esc(val(r.title))}</h3><p>${esc(val(r.text))}</p><div class="rule-bottom"><span>COREBOOK // ${String(i+1).padStart(2,'0')}</span><button class="rule-source" data-action="book-page" data-page="${esc(r.page)}">${state.lang==='ru'?'ОТКРЫТЬ':'OPEN'} ↗</button></div></article>`).join(''):`<div class="empty compact"><div class="empty-icon">⌕</div><p>${tr('noResults')}</p></div>`}
function dice(){return `<div class="page-header"><div><div class="overline">03 / PROBABILITY ENGINE</div><h1>${tr('diceTitle')}</h1><p>${tr('diceLead')}</p></div><div class="header-marker">⬡<small>RANDOM<br>GENERATOR</small></div></div><div class="dice-grid"><section class="card dice-card"><div class="card-heading"><span>${tr('check')}</span><span>01 / D10</span></div><div class="dice-visual">⬡<span>D10</span></div><h2>${tr('diceFormula')}</h2><p class="muted">${tr('critNote')}</p><div class="form-grid three"><label class="field">${tr('statValue')}<input type="number" id="roll-stat" value="${Number(state.diceValues.stat)||0}" min="0" max="20"></label><label class="field">${tr('skillValue')}<input type="number" id="roll-skill" value="${Number(state.diceValues.skill)||0}" min="0" max="20"></label><label class="field">${tr('modifier')}<input type="number" id="roll-mod" value="${Number(state.diceValues.modifier)||0}" min="-100" max="100"></label></div><button class="btn primary wide" data-action="roll-check">${tr('roll')} ↗</button></section><div><section class="card"><div class="card-heading"><span>${tr('freeRoll')}</span><span>02 / DICE</span></div><div class="form-grid two"><label class="field">${tr('number')}<input type="number" id="roll-count" min="1" max="50" value="${Number(state.diceValues.count)||1}"></label><label class="field">${tr('sides')}<select id="roll-sides">${[6,10,4,8,12,20,100].map(n=>`<option value="${n}" ${Number(state.diceValues.sides)===n?'selected':''}>${n}</option>`).join('')}</select></label></div><button class="btn ghost wide" data-action="roll-free">${tr('roll')} ↗</button></section><section class="card history-card"><div class="card-heading"><span>${tr('history')}</span><button class="text-link" data-action="clear-history">${tr('clear')}</button></div><div id="history-list">${historyRows()}</div></section></div></div>`}
function historyRows(){return state.history.length?state.history.map(r=>`<div class="history-row"><div><strong>${esc(r.label)}</strong><small>${esc(r.detail)}</small></div><b>${esc(r.total)}</b></div>`).join(''):`<p class="muted">${tr('noRolls')}</p>`}
function input(label,key,value,type='text',extra=''){return `<label class="field">${label}<input type="${type}" data-field="${key}" value="${esc(value)}" ${extra}></label>`}
function sheet(c){if(!c){state.view='characters';return characters()}const sum=statSum(c),used=points(c),max=hpMax(c),role=window.ROLES.find(r=>r.id===c.role),badReq=SKILLS.some(s=>s[4]&&Number(c.skills[s[0]])<2),quick=['streetrat','edgerunner'].includes(c.extra?.startingPack?.method);return `<div class="sheet-top"><button class="back-link" data-action="navigate" data-view="characters">← ${tr('back')} / ${tr('characters')}</button><span class="saved-indicator"><span class="status-dot"></span> <span data-app-save-status>${syncAdapter?syncAdapter.stateLabel():'…'}</span></span></div><div class="page-header sheet-header"><div><div class="overline">PERSONNEL FILE / ${esc(c.role.toUpperCase())}</div><h1 data-calc="character-name">${esc(c.name||tr('untitled'))}</h1><p data-calc="role-description">${esc(val(role?.description)||'')}</p></div><div class="header-actions"><button class="btn ghost" data-action="export">↓ ${tr('export')}</button><button class="btn ghost" data-action="print">↗ ${tr('print')}</button></div></div><div class="sheet-layout"><div class="sheet-primary"><section class="card"><div class="card-heading"><span>${tr('identity')}</span><span>01 / ID</span></div><div class="form-grid three">${input(tr('handle'),'name',c.name,'text',`placeholder="${tr('namePlaceholder')}" maxlength="80"`)}<label class="field">${tr('role')}<select data-field="role">${window.ROLES.map(r=>`<option value="${esc(r.id)}" ${c.role===r.id?'selected':''}>${esc(val(r.name))}</option>`).join('')}</select></label>${input(tr('roleRank'),'rank',c.rank,'number','min="1" max="10"')}</div></section><section class="card"><div class="card-heading"><span>${tr('stats')}</span><span data-calc="stats">${sum}${quick?'':' / 62'}</span></div><p class="muted">${quick?(state.lang==='ru'?'Характеристики по таблицам стартового метода.':'STATS from starting method tables.'):tr('statsHelp')}</p><div class="stats-grid">${STATS.map(s=>`<label class="stat"><span>${s}</span><input type="number" min="0" max="20" data-stat="${s}" value="${Number(c.stats[s])}"></label>`).join('')}</div><div data-calc="stat-budget" class="budget-line ${quick||sum===62&&validStartingStats(c)?'good':'warn'}"><span>${quick?(state.lang==='ru'?'● Табличное создание':'● Table-based creation'):sum===62&&validStartingStats(c)?'● '+tr('statBudgetOk'):'● '+tr('spendWarn')}</span><b>${quick?'':tr('remaining')+': '+(62-sum)}</b></div></section><section class="card"><div class="card-heading"><span>${tr('skills')}</span><span data-calc="skills">${used}${quick?'':' / 86'}</span></div><p class="muted">${quick?(state.lang==='ru'?'Навыки стартового метода.':'Starting method skills.'):tr('skillsHelp')}</p><div class="skills-list">${SKILLS.map(s=>`<div class="skill-row"><div><strong>${esc(state.lang==='ru'?s[1]:s[0])}</strong><small>${s[2]} ${s[3]===2?' · ×2':''}${s[4]?' · '+tr('required'):''}</small></div><input aria-label="${esc(state.lang==='ru'?s[1]:s[0])}" type="number" data-skill="${esc(s[0])}" value="${Number(c.skills[s[0]])||0}" min="0" max="10"><button class="skill-roll" data-action="skill-roll" data-skill="${esc(s[0])}" title="${tr('quickRoll')}">⬡</button></div>`).join('')}</div><div data-calc="skill-budget" class="budget-line ${quick||used===86&&!badReq&&!aboveStartingSkills(c)?'good':'warn'}"><span>${quick?(state.lang==='ru'?'Стартовый метод': 'Starting method'):badReq?tr('needSkill'):used===86&&!aboveStartingSkills(c)?tr('skillBudgetOk'):tr('spendWarn')}</span><b>${tr('skillPoints')}: ${used}${quick?'':'/86'}</b></div>${input(tr('native'),'native',c.native,'text',`placeholder="${tr('nativeHelp')}"`) }<p class="help">${tr('nativeHelp')}</p></section>${window.CharacterExtra.render(c,state.lang)}<div id="reload-tools-mount">${window.ReloadTools?.render(c,state.lang)||''}</div>${window.HustleTools?.render(c,state.lang)||''}${window.LifestyleTools?.render(c,state.lang)||''}${window.RoleTools.render(c,state.lang)}${window.EquipmentTools.render(c,state.lang)}<section class="card"><div class="card-heading"><span>${tr('inventory')}</span><span>04 / LOADOUT</span></div>${['gear','cyberware','notes'].map(k=>`<label class="field textarea-field">${tr(k)}<textarea data-field="${k}" placeholder="${tr('write')}" rows="4">${esc(c[k])}</textarea></label>`).join('')}</section><button class="delete-button" data-action="delete">✕ ${tr('delete')}</button></div><aside class="sheet-aside"><section class="card condition"><div class="card-heading"><span>${tr('vitals')}</span><span>02 / LIVE</span></div><div class="hp-display"><span>${tr('hp')}</span><div><input type="number" data-field="hp" min="-999" value="${Number(c.hp)||0}" aria-label="${tr('hp')}"><i data-calc="max-hp">/ ${max}</i></div><small>MAX HP</small></div><div class="condition-rows"><div><span>${tr('serious')}</span><strong data-calc="serious">&lt; ${Math.ceil(max/2)}</strong></div><div><span>${tr('death')}</span><strong data-calc="death">${Number(c.stats.BODY)}</strong></div><div><span>${tr('maxHumanity')}</span><strong data-calc="max-humanity">${Number(c.stats.EMP)*10}</strong></div><div><span>${tr('currentEmp')}</span><strong data-calc="current-emp">${Math.max(0,Math.floor(Number(c.humanity)/10))}</strong></div></div>${input(tr('humanity'),'humanity',c.humanity,'number','min="-999" max="1000"')}<div class="form-grid two">${input(tr('head')+' SP','head',c.head,'number','min="0"')}${input(tr('bodyArmor')+' SP','bodyArmor',c.bodyArmor,'number','min="0"')}</div></section><section class="note-card"><span>✳ ${tr('guide')}</span><p>${tr('sheetHint')}</p></section></aside></div>`}
function builderChoice(){let ru=state.lang==='ru';return `<div class="page-header"><div><div class="overline">COREBOOK / CHARACTER CREATION</div><h1>${ru?'СОЗДАНИЕ ПЕРСОНАЖА':'CREATE A CHARACTER'}</h1><p>${ru?'Выберите метод из Corebook. Каждый мастер позволяет сохранить черновик.':'Choose a Corebook method. Each builder can save a draft.'}</p></div></div><div class="quick-grid">${[['complete','Complete Package',ru?'Распределите характеристики, навыки и стартовый бюджет.':'Allocate STATs, skills and starting budgets.'],['streetrat','Streetrat',ru?'Готовые таблицы характеристик и навыков роли.':'Preset STAT and Role skill tables.'],['edgerunner','Edgerunner',ru?'Броски характеристик и распределение навыков роли.':'Roll STATs and allocate Role skills.']].map(([id,name,desc])=>`<button class="quick-card" data-action="start-builder" data-method="${id}"><span class="quick-icon">✳</span><span><b>${name}</b><small>${desc}</small></span><span class="quick-arrow">↗</span></button>`).join('')}</div>`}
function render(){if(window.SharedCampaigns?.shouldNavigate())state.view='campaigns';window.Lifepath?.setScope(syncAdapter?.getScope()||null);window.NetTools?.setScope(syncAdapter?.getScope()||null);window.MedicalTools?.setScope(syncAdapter?.getScope()||null);window.RepairTools?.setScope(syncAdapter?.getScope()||null);window.ReloadTools?.setScope(syncAdapter?.getScope()||null);if(state.view==='sheet')window.EquipmentTools.setScope(syncAdapter?.getScope()||null);let content=state.view==='overview'?overview():state.view==='characters'?characters():state.view==='rules'?rules():state.view==='dice'?dice():state.view==='catalog'?catalog():state.view==='campaigns'?window.Campaigns.render(state.campaigns,state.characters,state.lang)+(window.SharedCampaigns?.shell()||''):state.view==='book'?window.Book.render(state.lang):state.view==='net'?(syncAdapter?.getScope()?window.NetTools.render({lang:state.lang,architectures:state.netArchitectures}):'<div class="card">'+(state.lang==='ru'?'Дождитесь синхронизации и входа в аккаунт.':'Wait for sync and sign in.')+'</div>'):state.view==='gm'?(syncAdapter?.getScope()?window.GMTools.render({lang:state.lang,workspace:state.gmWorkspace}):'<div class="card">'+(state.lang==='ru'?'Дождитесь синхронизации и входа в аккаунт.':'Wait for sync and sign in.')+'</div>'):state.view==='medical'?(syncAdapter?.getScope()?window.MedicalTools.render({lang:state.lang,characters:state.characters}):'<div class="card">'+(state.lang==='ru'?'Дождитесь синхронизации и входа в аккаунт.':'Wait for sync and sign in.')+'</div>'):state.view==='repair'?(syncAdapter?.getScope()?window.RepairTools.render({lang:state.lang,characters:state.characters}):'<div class="card">'+(state.lang==='ru'?'Дождитесь синхронизации и входа в аккаунт.':'Wait for sync and sign in.')+'</div>')+(window.CraftingTools?.render(state.lang)||''):state.view==='combat'?window.CombatTools.render(state.lang)+(window.AutofireTools?.render(state.lang)||'')+(window.AreaTools?.render(state.lang)||'')+(window.GrappleTools?.render(state.lang)||'')+(window.VehicleTools?.render(state.lang)||'')+(window.MartialArts?.render(state.lang)||'')+window.WeaponReference.render(state.lang):state.view==='builder-choice'?builderChoice():state.view==='builder'?window.Builder.render(builderContext()):state.view==='quick-builder'?window.QuickBuilder.render(quickBuilderContext()):state.view==='lifepath'?window.Lifepath.render(state.lang,state.characters):sheet(active());$('#app').innerHTML=appShell(content);if(state.view==='campaigns')window.SharedCampaigns?.mount({scope:syncAdapter?.getScope()||null,getScope:()=>syncAdapter?.getScope()||null,lang:state.lang,characters:state.characters});document.documentElement.lang=state.lang;document.title='Night City // RED — '+tr('appLabel')}
