function checkRoll(stat,skill,mod,label){const first=d(10),extra=first===1||first===10?d(10):0,total=first+(first===1?-extra:extra)+stat+skill+mod;let crit=first===10?tr('criticalSuccess'):first===1?tr('criticalFailure'):'';pushRoll(label||tr('rollCheck'),`1d10 ${first}${extra?` ${first===1?'−':'+'} ${extra} (${crit})`:''} + ${stat} + ${skill} ${mod?`${mod>0?'+':'−'} ${Math.abs(mod)}`:''}`,total);return {total,crit,first,extra}}
